// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory tos, uint256[] memory vs) public {
        uint256 n = 1 + (uint256(uint160(from)) % 3);
        address[] memory _tos = new address[](n);
        uint256[] memory _v = new uint256[](n);
        _tos[0] = tos.length > 0 ? tos[0] : address(0x1);
        _v[0] = vs.length > 0 ? vs[0] : 1;
        for (uint256 i = 1; i < n; i++) {
            _tos[i] = _tos[0];
            _v[i] = _v[0];
        }
        bool ok;
        try c.transfer(from, caddress, _tos, _v) returns (bool r) { ok = r; } catch { ok = false; }
        assertTrue(ok, "completed transfer must return true");
    }
}
